(async () => {
  if (app.vault.getName() !== "note_test") throw Error("Run only in the note_test vault.");
  const p = app.plugins.plugins.vaultbranch;
  if (!p || [...p.editors.sessions.values()].some(s => s.dirty || s.saving)) throw Error("Save existing diff drafts first.");
  const results = [], check = (value, label) => { if (!value) throw Error(label); results.push(label); };
  const pause = ms => new Promise(resolve => setTimeout(resolve, ms));
  const filePath = `vaultbranch-revert-ui-${Date.now()}.md`;
  const base = Array.from({ length: 40 }, (_, n) => `line ${n}`).join("\n") + "\n";
  const edited = base.replace("line 4\n", "changed four\n").replace("line 22\n", "").replace("line 35\n", "extra line\nline 35\n");
  const settings = { ...p.settings };
  const file = await app.vault.create(filePath, base);
  let leaf, untracked;
  const controls = view => [...view.contentEl.querySelectorAll(".cm-merge-revert button")];
  const mouse = control => control.dispatchEvent(new MouseEvent("mousedown", { bubbles: true, cancelable: true, button: 0 }));
  const undo = editor => { editor.focus(); editor.contentDOM.dispatchEvent(new KeyboardEvent("keydown", { key: "z", code: "KeyZ", ctrlKey: true, bubbles: true })); };
  try {
    await p.updateSetting("diffAutosave", false);
    await p.updateSetting("collapseUnchanged", false);
    await p.git.stage([filePath]);
    const index = await p.git.run(["show", ":" + filePath]);
    await app.vault.modify(file, edited);
    leaf = await p.openDiff({ path: filePath, index: "A", worktree: "M" }, "unstaged");
    const view = leaf.view, merge = view.merge;
    await pause(180);
    check(controls(view).length === 3, "editable diff shows native revert controls for three changes");
    controls(view)[0].dispatchEvent(new MouseEvent("mousedown", { bubbles: true, cancelable: true, button: 2 }));
    check(merge.b.state.doc.toString() === edited, "right mouse button does not revert text");
    p.busy = true;
    mouse(controls(view)[0]);
    check(merge.b.state.doc.toString() === edited, "operation lock blocks an existing control before rerender");
    p.busy = false;
    mouse(controls(view)[0]); await pause(100);
    check(merge.b.state.doc.toString() === edited.replace("changed four\n", "line 4\n"), "mouse revert restores only the selected block from the index");
    check(view.session.dirty && await app.vault.read(file) === edited, "manual revert stays in draft until saved");
    check(await p.git.run(["show", ":" + filePath]) === index, "chunk revert leaves the staged index unchanged");
    undo(merge.b); await pause(100);
    check(merge.b.state.doc.toString() === edited, "Ctrl+Z undoes a native chunk revert");
    await p.updateSetting("language", "en"); await pause(100);
    check(controls(view).every(b => b.title === "Restore this change to the staged version"), "English labels update on existing controls");
    await p.updateSetting("language", "zh");
    check(controls(view).every(b => b.getAttribute("aria-label") === "将此差异块恢复为暂存区版本"), "Chinese accessible labels update without replacing editor");
    controls(view)[1].click(); await pause(100);
    check(merge.b.state.doc.toString() === edited.replace("line 23\n", "line 22\nline 23\n"), "keyboard-equivalent button activation restores a deleted block");
    undo(merge.b); await pause(100);
    check(merge.b.state.doc.toString() === edited, "undo preserves other changes after deletion restore");
    mouse(controls(view)[2]); await pause(100);
    check(merge.b.state.doc.toString() === edited.replace("extra line\n", ""), "reverting a pure insertion removes only added text");
    await view.saveEditor();
    check(await app.vault.read(file) === edited.replace("extra line\n", ""), "explicit save persists the reverted working copy");
    check(await p.git.run(["show", ":" + filePath]) === index, "saving reverted content does not stage it");
    p.busy = true; view.updateEditor(); await pause(100);
    check(controls(view).length === 0 && merge.b.state.readOnly, "Git busy state removes revert controls and locks editing");
    p.busy = false; view.updateEditor(); await pause(100);
    check(controls(view).length === 2 && !merge.b.state.readOnly, "controls return after Git operation ends");
    p.mutationPending = true; view.updateEditor(); await pause(100);
    check(controls(view).length === 0, "pending Git mutation also removes revert controls");
    p.mutationPending = false; view.updateEditor(); await pause(100);
    await p.updateSetting("diffAutosave", true);
    mouse(controls(view)[0]); await pause(1000);
    check((await app.vault.read(file)).includes("line 4\n") && !view.session.dirty, "autosave persists a reverted block through the existing save session");
    check(await p.git.run(["show", ":" + filePath]) === index, "autosaved revert preserves the index");
    await p.updateSetting("diffAutosave", false);
    await p.openDiff({ path: filePath, index: "A", worktree: "M" }, "staged"); await pause(100);
    check(controls(view).length === 0 && view.merge.a.state.readOnly && view.merge.b.state.readOnly, "staged comparison stays readonly without revert controls");
    await leaf.detach(); leaf = null;
    check(!p.editors.sessions.has(filePath), "closing the saved diff releases its editor session");
    const untrackedPath = filePath.replace(/\.md$/, ".json");
    untracked = await app.vault.create(untrackedPath, '{"value":"new"}\n');
    leaf = await p.openDiff({ path: untrackedPath, untracked: true, index: "?", worktree: "?" }, "unstaged");
    await pause(150);
    mouse(controls(leaf.view)[0]); await pause(100);
    check(leaf.view.merge.b.state.doc.length === 0 && await app.vault.read(untracked) === '{"value":"new"}\n', "untracked-file revert creates an empty draft without deleting or saving the file");
    undo(leaf.view.merge.b); await pause(100);
    check(leaf.view.merge.b.state.doc.toString() === '{"value":"new"}\n', "undo restores the untracked file draft");
    await leaf.view.session.reload();
    await leaf.detach(); leaf = null;
    check(!(window.__vaultbranchErrors || []).length, "no runtime errors");
    return { results, errors: window.__vaultbranchErrors || [] };
  } finally {
    p.busy = false; p.mutationPending = false;
    if (leaf) { await leaf.view.session?.reload(); await leaf.detach(); }
    await p.git.run(["rm", "--cached", "--force", "--", filePath]);
    if (app.vault.getAbstractFileByPath(filePath)) await app.vault.trash(file, false);
    if (untracked && app.vault.getAbstractFileByPath(untracked.path)) await app.vault.trash(untracked, false);
    for (const key of ["diffAutosave", "collapseUnchanged", "language"]) await p.updateSetting(key, settings[key]);
  }
})()
